      { id: "junior-education", word: "education", ipa: "/ˌedʒuˈkeɪʃən/", en: "the process of teaching and learning", zh: "教育", example: "Good education opens doors to the future.", exampleZh: "良好的教育开启通往未来的大门。", tip: "书本变成钥匙，education 帮你打开未来之门。", visual: V("🎓", "Books and a graduation cap opening a door to the future", "#4F46E5", "#FBBF24"), breakdown: S(["ed", "/ˌedʒ/"], ["u", "/u/"], ["ca", "/ˈkeɪ/"], ["tion", "/ʃən/"]) },
      { id: "junior-important", word: "important", ipa: "/ɪmˈpɔːtənt/", en: "having great value or influence", zh: "重要的", example: "Sleep is important for a healthy body.", exampleZh: "睡眠对健康的身体很重要。", tip: "在 important 的事旁画一颗醒目的大星星。", visual: V("❗", "An important note glowing with a large star and exclamation mark", "#EF4444", "#FDE047"), breakdown: S(["im", "/ɪm/"], ["por", "/ˈpɔː/"], ["tant", "/tənt/"]) },
      { id: "junior-knowledge", word: "knowledge", ipa: "/ˈnɒlɪdʒ/", en: "information and understanding gained through learning", zh: "知识", example: "Books give us knowledge about the world.", exampleZh: "书本带给我们关于世界的知识。", tip: "开头 k 不发音；knowledge 像大脑里不断长大的知识树。", visual: V("🌳", "A knowledge tree growing books, numbers and planets", "#16A34A", "#60A5FA"), breakdown: S(["know", "/ˈnɒ/"], ["ledge", "/lɪdʒ/"]) },
      { id: "junior-protect", word: "protect", ipa: "/prəˈtekt/", en: "to keep someone or something safe", zh: "保护", example: "This helmet will protect your head.", exampleZh: "这顶头盔会保护你的头部。", tip: "pro-（在前面）+ tect（遮盖）：挡在前面提供保护。", visual: V("🛡️", "A bright shield protecting a child from falling objects", "#2563EB", "#93C5FD"), breakdown: R("前缀 + 词根", ["pro", "在前；向前", "/prə/"], ["tect", "遮盖", "/ˈtekt/"]) },
      { id: "junior-science", word: "science", ipa: "/ˈsaɪəns/", en: "the study of the natural world through observation", zh: "科学", example: "We did an exciting experiment in science class.", exampleZh: "我们在科学课上做了一个有趣的实验。", tip: "science 里的 c 不单独发音；想象烧杯冒出探索的泡泡。", visual: V("🔬", "A colourful science experiment bubbling beside a microscope", "#06B6D4", "#A78BFA"), breakdown: S(["sci", "/ˈsaɪ/"], ["ence", "/əns/"]) },
      { id: "junior-volunteer", word: "volunteer", ipa: "/ˌvɒlənˈtɪə/", en: "a person who offers to help without being paid", zh: "志愿者；自愿做", example: "I volunteer at the animal centre on Sundays.", exampleZh: "我每周日去动物中心做志愿者。", tip: "主动举手帮助别人，就是 volunteer。", visual: V("🙌", "A smiling volunteer caring for pets at a community centre", "#10B981", "#FB7185"), breakdown: S(["vol", "/ˌvɒl/"], ["un", "/ən/"], ["teer", "/ˈtɪə/"]) }
