      { id: "toefl-undergo", word: "undergo", ipa: "/ˌʌndəˈɡəʊ/", en: "to experience a process, change or treatment", zh: "经历；经受", example: "The building will undergo major repairs.", exampleZh: "这栋建筑将进行大修。", tip: "under + go：从一个过程下面穿过去，就是亲身经历。", visual: V("🔧", "A building undergoing repairs from old to renewed", "#64748B", "#FBBF24"), breakdown: R("复合动词", ["under", "在……之下；经历中", "/ˌʌndə/"], ["go", "去；进行", "/ˈɡəʊ/"]) }
